const cfg = $('Configuration').first().json;
const raw = $input.first().json.data;
const candles = (typeof raw === 'string' ? JSON.parse(raw) : raw)
  .map(c => ({ time: Number(c[0]), close: Number(c[4]) }))
  .filter(c => Number.isFinite(c.close))
  .sort((a, b) => a.time - b.time);
const maDays = Number(cfg.MA_DAYS) || 200;
if (candles.length < maDays) {
  throw new Error(`Not enough candles (${candles.length}) for a ${maDays}-day moving average`);
}
const closes = candles.map(c => c.close);
const lastClose = closes[closes.length - 1];
const window = closes.slice(closes.length - maDays);
const ma = window.reduce((s, v) => s + v, 0) / window.length;
const aboveMa = lastClose >= ma;
const multiplier = aboveMa ? Number(cfg.MULTIPLIER_ABOVE_MA) : Number(cfg.MULTIPLIER_BELOW_MA);
const amountEur = Math.round(Number(cfg.DCA_AMOUNT_EUR) * multiplier * 100) / 100;
return [{ json: {
  product_id: cfg.PRODUCT_ID,
  date: new Date().toISOString(),
  last_close: lastClose,
  ma_days: maDays,
  ma_value: Math.round(ma * 100) / 100,
  ratio: Math.round((lastClose / ma) * 1000) / 1000,
  regime: aboveMa ? 'BULLISH (price > MA)' : 'BEARISH (price < MA)',
  multiplier,
  amount_eur: amountEur
} }];

const s = $input.first().json;
const esc = t => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const num = v => Number(v).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const head = `📊 DCA signal ${s.product_id} — ${s.date.slice(0, 10)}\nPrice: ${num(s.last_close)} | MA${s.ma_days}: ${num(s.ma_value)} (x${s.ratio})\nRegime: ${s.regime} → multiplier x${s.multiplier}`;
const body = s.amount_eur < 1
  ? '⏸ Signal: pause this week (amount < 1).'
  : `👉 Suggested amount this week: ${num(s.amount_eur)}.\n(No order is placed: this workflow only computes the signal.)`;
return [{ json: { text: esc(`${head}\n\n${body}`) } }];
